// Build summary for the agent and handoff message for the lead.
const conv = $('Switch to Human Mode').first().json;
const agent = $('Fetch Agent Details').first().json;
const historyItems = $('Fetch Recent Messages').all();

// Build conversation summary
const history = historyItems
  .map(i => i.json)
  .filter(m => m.body)
  .reverse();

let summary = history.map(m => {
  const who = m.sender_type === 'lead' ? 'Lead' : 'AI';
  return `${who}: ${m.body.substring(0, 150)}`;
}).join('\n');

if (!summary) summary = '(Sin historial previo)';

// Message to agent
const agentMsg = [
  `\u{1F6A8} *Handoff - Lead requiere atencion humana*`,
  ``,
  `\u{1F464} Lead: ${conv.lead_name || 'Sin nombre'}`,
  `\u{1F4F1} Telefono: ${conv.lead_phone}`,
  `\u{1F3E0} Propiedad: ${conv.current_property || 'No especificada'}`,
  ``,
  `*Resumen de conversacion:*`,
  summary.substring(0, 800),
  ``,
  `El lead necesita hablar contigo directamente. Sus mensajes ahora te llegaran a ti.`
].join('\n');

// Message to lead
const leadMsg = [
  `Te estoy conectando con ${agent.name || 'un asesor'}, quien te atendera personalmente.`,
  ``,
  `${agent.name || 'Tu asesor'} se pondra en contacto contigo en breve. Si necesitas algo urgente, puedes escribirle directamente.`,
  ``,
  `I'm connecting you with ${agent.name || 'an agent'} who will assist you personally. They'll be in touch shortly.`
].join('\n');

return [
  { json: { target: 'agent', number: agent.whatsapp_number, text: agentMsg, conversation_id: conv.conversation_id } },
  { json: { target: 'lead', number: conv.lead_phone, text: leadMsg, conversation_id: conv.conversation_id } }
];
